type Grade = { score?: number | null; status: string; feedback?: string; suggestion?: string; reference?: string; error?: string };
type GradingMode = 'mixed' | 'ai';
type Exam = { id: string; title: string; level: string; mode: string; source?: string; gradingMode?: GradingMode; gradingModeLocked?: boolean; status: string; createdAt?: string; submittedAt?: string | null; questions: Question[]; annotations?: ExamAnnotation[]; answers: Record<string, string>; grades: Record<string, Grade>; score?: number; maxScore: number };
type ExamSummary = Pick<Exam, 'id' | 'title' | 'level' | 'mode' | 'gradingMode' | 'status' | 'createdAt' | 'score' | 'maxScore'>;
type Conversation = { id: string; title?: string; createdAt?: string; messages?: { role: string; content: string }[] };
type Auth = { connected: boolean; planAuthorized: boolean; account?: { email?: string; name?: string; plan?: string }; usageUrl?: string; limitations?: string; error?: string; lastError?: { code: string; message: string }; welcomeNeeded?: boolean };
type Runtime = { dataDir: string; database: string; credentialDir: string; backups: string; localRequests?: { hour: number; day: number; hourlyLimit: number; dailyLimit: number } };
type Dashboard = { stats: { answered: number; accuracy: number; exams: number; words: number }; weakPoints: { name: string; accuracy: number; attempts: number }[]; recent: ExamSummary[]; reviews: { id: string; title: string; reason: string; level: string }[]; activity: { date: string; count: number }[] };
type Mistake = { id: string; question: Question; level: string; type: string; knowledgePoints: string[]; errors: number; lastPracticed?: string; examId: string };
type KnowledgePoint = { name: string; level: string; questionCount: number; attempts: number; correct: number; accuracy: number | null; lastPracticed: string | null; lastGenerated: string; examId: string };
type DeleteScope = 'exam' | 'conversation' | 'exams' | 'mistakes' | 'saved' | 'conversations' | 'cache' | 'all';
