const dataCountNames: Record<string, string> = { exams: '试卷', answers: '作答答案', grades: '评分记录', mistakes: '错题', saved: '生词与收藏', conversations: '讲解对话', messages: '对话消息', cache: '讲解缓存', reports: '题目疑问记录', gradingEvents: '评分统计事件', annotations: '词句标记与解析' };
